TLM.f("Sancti/08-29",{"officium":"Decollatione S. Joannis Baptistæ","rule":["ex C2;","Gloria"],"fallback":"Commune/C2","from":{"GradualeP":"Commune/C2","Tractus":"Commune/C2"},"sections":{"Introitus":[{"k":"ref","la":"Ps 118:46-47"},{"k":"text","la":"Loquébar de testimóniis tuis in conspéctu regum, et non confundébar: et meditábar in mandátis tuis, quæ diléxi nimis."},{"k":"ref","la":"Ps 91:2"},{"k":"text","la":"Bonum est confitéri Dómino: et psállere nómini tuo, Altíssime."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Loquébar de testimóniis tuis in conspéctu regum, et non confundébar: et meditábar in mandátis tuis, quæ diléxi nimis."}],"Oratio":[{"k":"text","la":"Sancti Joánnis Baptístæ Præcursóris et Martyris tui, quǽsumus, Dómine, veneránda festívitas: salutáris auxílii nobis præstet efféctum:"},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Léctio Jeremíæ Prophétæ"},{"k":"ref","la":"Jer 1:17-19"},{"k":"text","la":"In diébus illis: Factum est verbum Dómini ad me, dicens: Accínge lumbos tuos, et surge, et lóquere ad Juda ómnia, quæ ego præcípio tibi. Ne formides a fácie eórum: nec enim timére te fáciam vultum eórum. Ego quippe dedi te hódie in civitátem munítam, et in colúmnam férream, et in murum æreum, super omnem terram, régibus Juda, princípibus ejus, et sacerdótibus, et pópulo terræ. Et bellábunt advérsum te, et non prævalebunt: quia ego tecum sum, ait Dóminus, ut líberem te."}],"Graduale":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem."},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Osee 14:6"},{"k":"text","la":"Justus germinábit sicut lílium: et florébit in ætérnum ante Dóminum. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 111:1-2"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 20:3-4"},{"k":"text","la":"Desidérium ánimæ ejus tribuísti ei: et voluntáte labiórum ejus non fraudásti eum."},{"k":"text","la":"Quóniam prævenísti eum in benedictiónibus dulcédinis.","mark":"V"},{"k":"text","la":"Posuísti in cápite ejus corónam de lápide pretióso.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Marcum"},{"k":"ref","la":"Marc 6:17-29"},{"k":"text","la":"In illo témpore: Misit Heródes, ac ténuit Joánnem, et vinxit eum in cárcere propter Herodíadem, uxorem Philíppi fratris sui, quia dúxerat eam. Dicebat enim Joánnes Heródi: Non licet tibi habére uxórem fratris tui. Heródias autem insidiabátur illi, et volébat occídere eum, nec póterat. Heródes enim metuébat Joánnem, sciens eum virum justum et sanctum: et custodiébat eum, et audíto eo multa faciébat, et libénter eum audiébat. Et cum dies opportúnus accidísset, Heródes natális sui cœnam fecit princípibus et tribúnis et primis Galilææ. Cumque introísset fília ipsíus Herodíadis, et saltásset, et placuísset Heródi simúlque recumbéntibus; rex ait puéllæ: Pete a me, quod vis, et dabo tibi. Et jurávit illi: Quia quidquid petiéris dabo tibi, licet dimídium regni mei. Quæ cum exiísset, dixit matri suæ: Quid petam? At illa dixit: Caput Joánnis Baptístæ. Cumque introísset statim cum festinatióne ad regem, petívit dicens: Volo, ut protínus des mihi in disco caput Joánnis Baptístæ. Et contristátus est rex: propter jusjurándum et propter simul discumbéntes nóluit eam contristáre: sed misso spiculatóre, præcépit afférri caput ejus in disco. Et decollávit eum in cárcere. Et áttulit caput ejus in disco: et dedit illud puéllæ, et puella dedit matri suæ. Quo audíto, discípuli ejus venérunt et tulérunt corpus ejus: et posuérunt illud in monuménto."}],"Offertorium":[{"k":"ref","la":"Ps 20:2-3"},{"k":"text","la":"In virtúte tua, Dómine, lætábitur justus, et super salutáre tuum exsultábit veheménter: desidérium ánimæ ejus tribuísti ei. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Múnera, quæ tibi, Dómine, pro sancti Martyris tui Joánnis Baptístæ passióne deférimus: quǽsumus; ut ejus obténtu nobis profíciant ad salútem."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, in cápite ejus corónam de lápide pretióso."}],"Postcommunio":[{"k":"text","la":"Cónferat nobis, Dómine, sancti Joánnis Baptístæ sollémnitas: ut et magnífica sacraménta, quæ súmpsimus, significáta venerémur, et in nobis pótius édita gaudeámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"aacbc696a132edd5":{"t":"Ps 118, 46-47, Ps 91, 2\n(Ps 118, 46-47) Govorio sam pred kraljevima o tvojim odredbama i nisam se smeo, i razmišljao sam o tvojim zapovijedima koje veoma ljubim. (Ps 91, 2) Dobro je slaviti Gospodina, i pjevati tvojemu imenu, Svevišnji.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 118, 46-47) Govorio sam pred kraljevima o tvojim odredbama i nisam se smeo, i razmišljao sam o tvojim zapovijedima koje veoma ljubim.","kn":"(Ps. 118, 46). Pred kraljevima sam govorio o zapovijedima Tvojim i niBam se bojao; razmatrao sam Tvoj zakon, koji ljubim veoma. (Ps. 919, 2.) Dobro je priznavati Gospodina i pjevati Imenu Tvojemu, Višnji! Slava Ocu . . . Pred kraljevima . . .","knRef":"Kniewald 1942, str. 694–695 (snimka 348) (OCR)"},"fb5b0b58ef3a9061":{"t":"<i>Pomolimo se</i>.\nČasna svetkovina svetog Ivana Krstitelja tvoga preteče i mučenika dala nam, molimo, Gospodine, učinak spasonosne pomoći:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, da nam časna svetkovina svetog Ivana Krstitelja, preteče i mučenika Tvoga, udijeli učinak spaisonosne pomoći, . koji živiš ...","knRef":"Kniewald 1942, str. 694–695 (snimka 348) (OCR)"},"396898a2e7710d60":{"t":"Jr 1, 17-19\nČitanje Jeremije proroka. U one dane reče mi Gospodin: Opaši svoje bokove, ustani i reci Judi sve što ti ja zapovijedam. Nemoj se bojati pred njima, jer ne dopuštam da ih se plašiš. Učinio sam te danas tvrdim gradom, željeznim stupom, mjedenim zidom za čitavu zemlju protiv kraljeva Judeje, njezinih knezova, svećenika i naroda zemlje. Svi će se oni boriti protiv tebe, ali te neće nadjačati jer sam ja uza te da te oslobodim, govori Gospodin.","kn":"Čitanje proroka Jeremije (1, 17-19). U one dane bila ml je upravljena Gospodnja riječ; Opaši svoje bokove, ustani i reci Judi sve, što ti ja zapovijedam. Nemoj se pred' njima bojati, jer ne ću dopustiiti, da se plašiš njihova lica. Učinio sam te danas tvrdim gradom i željeznim stupom i mjedenim zidom za svu zemlju proti kraljevima Judeje, njezinim knezovima, svećenicima i narodu zemlje. Oni će se boriti protiv tebe, ali te ne će nadjačati. jer sam ja uza te, da te oslobodim, govori Gospodin.","knRef":"Kniewald 1942, str. 694–695 (snimka 348) (OCR)"},"5df2315bb2a3c74a":{"t":"Ps 91, 13-14, Ps 91, 3\n(Ps 91, 13-14) Kao palma cvjeta i kao libanski cedar raste pravednik u domu Gospodnjem. (Ps 91, 3) Jutrom naviješta milosrđe tvoje i noću tvoju vjernost.\n\nHoš 14, 6\n<i>Aleluja</i>, <i>aleluja</i>.\nPravednik raste kao ljiljan i vječno cvate pred Gospodinom. <i>Aleluja</i>.","kn":"(Ps. 91, 13, 14). Pravednik i’aste poput paome i libanonskog cedra u domu Gospodnjem. Ra.no jutrom naviješta Tvoje milosrđe i noću Tvoju vjernost.\n\nAleluja, aleluja (Osee, 14, 6.) Pravednik raste poput ljilja.na i cvate pred Gospodinom u vjekove, aleluja.","knRef":"Kniewald 1942, str. 786–787 (snimka 394) (OCR)"},"fcbbb8e6fb9bf3af":{"t":"Mk 6, 17-29\nSlijedi sveto Evanđelje po Marku. U ono vrijeme po Herodovoj zapovijedi uhvate Ivana i okovana bace u tamnicu zbog Herodijade, žene brata Filipa, koju je Herod uzeo kao svoju ženu. Ivan je govorio Herodu: Ne smiješ imati žene svojega brata! Herodijada mu je zato radila o glavi. Ali nije mogla ništa, jer se Herod bojao Ivana znajući da je pravedan i svet čovjek. Štitio ga je, rado ga slušao i u mnogom se ravnao po njegovim uputama. A pruži se zgoda, kada je Herod na svoj rođendan priredio gozbu svojim knezovima, časnicima i galilejskim prvacima, uđe Herodijadina kći, plesaše i svidje se Herodu i gostima za stolom, i kralj reče djevojci: Zatraži od mene što god hoćeš i dat ću ti. Zakle joj se: Što god zatražiš, dat ću ti, pa bilo i polovicu mojega kraljevstva. Ova izađe i upita svoju majku: Što da zatražim? Ona joj odgovori: Glavu Ivana Krstitelja! Požuri se natrag kralju i zatraži: Hoću odmah na pladnju glavu Ivana Krstitelja. Kralj se ražalosti, ali zbog zakletve i gostiju za stolom nije ju htio odbiti, nego pošalje krvnika a zapovjedi da na pladnju donese Ivanovu glavu. I u tamnici odsiječe mu glavu, donese je na pladnju, preda djevojci, a ona svojoj majci. Kad su to dočuli učenici, dođu, uzmu njegovo tijelo i polože u grob.","kn":"t Slijedi sveto evanđelje po Marku (6, 17-29). U ono vrijeme posla Herod i uhvati Ivana i sveza ga u tamnici radi Herodijade, žene svojega brata Filipa, koju je doveo k sebi. Jer je Ivan govorio Herodu: Ne smiješ imati žene svojega brata;! Zato mu je Herodijada radila o glavi. Ali nije mogla, jer se Henoid bojao Ivana znajući, da je pravedan i svet čovjek. I štitio ga je, rado ga slušao, i radio mnoge stvari po njegovim riječima. A, dođe podesan dan, kad je Herod na svoj rođendan priredio gozbu svojim prvacima, vojvodama i knezovima galilejskim. Kad je Herpdijadina kći. unišla, plesala je i svidjela se Herodu i gostima za stolom, reče kralj djevojci: Išti od mene, što hoćeš 1. ja ću ti dati. I zakleo joj se: Štogod zaišteš, dat ću ti, pa bilO' i P'Oiovicu moga kraljevstva;. Ona, iziđe i upita .svoju majku: Što ću tražiti? Ona joj odgovori: Glavu Ivana Krstitelja! Odmah se požuri kralju i zaište: Hoću, da ml odmah na pladnju dadeš glavu Ivana Krstitelja. 1 ražalosti se kralj, ali je nije htio rastužiti radi zakletve i radi gostiju za .stolom, posla krvnika ,i zapovjedi, da na pladnju donesu njegovu glavu. I odsiječe mu glavu u tamnici,, donese je na pladnju i dade je djevo-jci, a djevojka svojoj majci. Kad su to dočuli njegovi učenici, dođoše i uzeše njegovo' tijelo i pol'ožiše u grob.","knRef":"Kniewald 1942, str. 694–695 (snimka 348) (OCR)"},"4e296f3326e0e479":{"t":"Ps 20, 2-3\nU jakosti tvojoj, Gospodine, raduje se pravednik i kliče radi tvoga spasenja, jer si mu ispunio želju srca njegova.","kn":"(Ps. 20, 2-'3). U kreposti Tvojoj Gospodine, raduje se pravednik i kliče nad spasenjem Tvojim, jer si mu ispunio želju duše njegove.","knRef":"Kniewald 1942, str. 818–819 (snimka 410) (OCR)"},"c3f0a131145c38b4":{"t":"Darovi, koje ti prinosimo, Gospodine, prigodom muke tvoga svetoga mučenika Ivana Krstitelja, molimo, da nam po njegovu zagovoru koriste za spasenje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Mo'limo, Gospodine, da nam usko-riste za spasenje darovi, što Ti ih prinosimo o spomenu mučendštvai Tvo'ga preteče, svetog Ivana Krstitelja, koji živiš i kraljuješ ...","knRef":"Kniewald 1942, str. 696–697 (snimka 349) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"f865cc96d8c6795d":{"t":"Ps 20, 4\nOkrunio si ga, Gospodine, krunom od dragoga kamenja.","kn":"(Ps. 20, 4). Postavio si, Gospoidine, na glavu njegovu krunu od dragoga kamenja.","knRef":"Kniewald 1942, str. 696–697 (snimka 349) (OCR)"},"6d5be1986868ad1d":{"t":"<i>Pomolimo se</i>.\nNeka nam dade, Gospodine, svetkovina svetog Ivana Krstitelja da častimo što označuju uzvišena otajstva koja smo primili i da se još više radujemo njihovu djelovanju u nama.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Udijelila nam, Gospodine, svetkovina svetog Ivana Krstitelja, da poštujemo ono, što označuju otajstva, koja smo primili, i da se radujemo radi njihova učinka u nama, po G. n.","knRef":"Kniewald 1942, str. 696–697 (snimka 349) (OCR)"}}});
